export default async (_ctx, client) => {
  const { behaviors } = await client.behaviors.list({});
  if (!behaviors?.length) return { note: "no behaviors in this org" };
  const b = await client.behaviors.get({ behavior_id: String(behaviors[0].id) });
  const keys = Object.keys(b ?? {}).sort();
  return {
    sampled_behavior_id: behaviors[0].id,
    has_scheduler_client_id: keys.includes("scheduler_client_id"),
    has_agent_kind_sibling: keys.includes("agent_kind"),
    has_device_worker_id_sibling: keys.includes("device_worker_id"),
    keys,
  };
};

export default async (_ctx, client) => {
  const { behaviors } = await client.behaviors.list({});
  return { count: behaviors?.length ?? 0, first_keys: Object.keys(behaviors?.[0] ?? {}).sort(), first: behaviors?.[0] };
};

export default async (_ctx, client) => {
  const b = await client.behaviors.get({ behavior_id: "71" });
